type WorldStateHandle = {
  entities: Record<string, string>;
};

const VOK = "Vok";
const PEX = "pex";
const DOR = "dor";

const copyState = (state: WorldStateHandle): WorldStateHandle => ({
  entities: { ...state.entities },
});

export const protocol: WorldProtocol<WorldStateHandle> = {
  reset(): WorldStateHandle {
    return { entities: { [VOK]: PEX } };
  },

  applyOperation(state, operationDisplayName) {
    const currentState = state.entities[VOK];

    if (operationDisplayName === "recoverVok") {
      if (currentState !== DOR) {
        return {
          success: false,
          error: `recoverVok requires Vok to be in ${DOR}`,
        };
      }

      const newState = copyState(state);
      newState.entities[VOK] = PEX;
      return { success: true, newState };
    }

    if (operationDisplayName === "advanceVok") {
      if (currentState !== PEX) {
        return {
          success: false,
          error: `advanceVok requires Vok to be in ${PEX}`,
        };
      }

      const newState = copyState(state);
      newState.entities[VOK] = DOR;
      return { success: true, newState };
    }

    return {
      success: false,
      error: `Unknown operation: ${operationDisplayName}`,
    };
  },

  getEntityState(state, entityDisplayName) {
    return state.entities[entityDisplayName] ?? "unknown";
  },

  toAbstractSnapshot(state) {
    return { ...state.entities };
  },
};
